/// <summary>
/// Enable/disable AVASubcontractorOrderPrintMail
/// </summary>
/// <param name = "_enable">boolean</param>
public void avaEnableSubcontractorOrderPrintMail(boolean _enable = true)
{
    boolean avaEnable = _enable && PurchOrderReport.enabled();
    AVASubcontractorOrderPrintMail.enabled(avaEnable);
}
